// The TCP ports this Mac listens on, from lsof: one row each, with the program and its PID; Return copies the port.
import { Action, ActionPanel, Icon, List } from "@raycast/api";
import { execFileSync } from "node:child_process";

type Port = { port: string; address: string; command: string; pid: string };

function listening(): Port[] {
  let out = "";
  try {
    out = execFileSync("/usr/sbin/lsof", ["-nP", "-iTCP", "-sTCP:LISTEN"], { encoding: "utf8", timeout: 2000 });
  } catch {
    return []; // lsof exits 1 when nothing listens
  }
  const seen = new Set<string>();
  const ports: Port[] = [];
  for (const line of out.split("\n").slice(1)) {
    const cols = line.trim().split(/\s+/);
    if (cols.length < 9) continue;
    const name = cols[8];
    const at = name.lastIndexOf(":");
    const port = name.slice(at + 1);
    const key = `${port}/${cols[1]}`;
    if (at < 0 || seen.has(key)) continue;
    seen.add(key);
    ports.push({ port, address: name.slice(0, at), command: cols[0], pid: cols[1] });
  }
  return ports.sort((a, b) => Number(a.port) - Number(b.port));
}

export default function Command() {
  const ports = listening();
  return (
    <List searchBarPlaceholder="Filter by port or program">
      {ports.length === 0 ? (
        <List.EmptyView icon={Icon.Plug} title="Nothing is listening" description="No TCP port is open for listening." />
      ) : (
        ports.map((p) => (
          <List.Item
            key={`${p.port}-${p.pid}`}
            icon={Icon.Plug}
            title={p.port}
            subtitle={p.command}
            accessories={[{ text: `PID ${p.pid}` }, { text: p.address }]}
            actions={
              <ActionPanel>
                <Action.CopyToClipboard title="Copy Port" content={p.port} />
                <Action.CopyToClipboard title="Copy PID" content={p.pid} />
              </ActionPanel>
            }
          />
        ))
      )}
    </List>
  );
}

